import { describe, it, expect, vi } from 'vitest';

vi.mock('~/env.mjs', () => ({ env: { NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test' } }));

vi.mock('react', async (importOriginal) => {
  const actual = await importOriginal<Record<string, unknown>>();
  return {
    ...actual,
    useCallback: (fn: unknown) => fn,
    // `useApiMethods` uses `useState` for the row-E `pendingSaveChoice` the persist gate sets, so
    // mocking only `useCallback` leaves the factory throwing outside a render. This stub holds a
    // value per call site, which is all this suite needs: no fixture here is row E, so
    // `setPendingSaveChoice` is never reached — and if the gate ever DID trip,
    // `loadAndSaveViaShippedProvider` throws 'save never reached the API layer' rather than
    // passing silently.
    useState: (initial: unknown) => {
      let value = typeof initial === 'function' ? (initial as () => unknown)() : initial;
      return [value, (next: unknown) => {
        value = typeof next === 'function' ? (next as (p: unknown) => unknown)(value) : next;
      }];
    },
  };
});
vi.mock('react-toastify', () => ({
  toast: Object.assign(() => 0, { dismiss: () => {}, loading: () => 0, update: () => {} }),
}));

import { validateMessage } from '~/utils/limits';
import {
  stripKeys, jsonModalSeed, resolveContentLoss, applyDisposition,
} from '~/utils';
import { discordMessageImportShape } from '~/server/api/utils/shapes';
import { IS_COMPONENTS_V2_FLAG } from '~/constants';
import useApiMethods from '~/providers/MessageProvider/useApiMethods';
import { switchToV2, switchToClassic } from '~/utils/messageMode';

type Draft = { flags?: number; content?: string; embeds?: unknown[]; components?: { type: number }[] };

describe('JSON-editor Load->save, executed end to end', () => {
  function loadAndSaveViaShippedProvider(stored: any, validated: unknown) {
    let state: any = stored;
    const messageRef: any = { current: state };
    const setMessage: any = (updater: any) => {
      state = typeof updater === 'function' ? updater(state) : updater;
      messageRef.current = state;
    };
    const upserted: any[] = [];
    const { updateMessage, saveMessage } = useApiMethods(
      messageRef,
      { current: false } as any,
      setMessage,
      async () => undefined,
      (opts: any) => { upserted.push(opts); },
      () => {},
    );
    updateMessage({ data: validated } as any);
    saveMessage();
    if (upserted.length !== 1) throw Error('save never reached the API layer');
    return upserted[0].message;
  }

  function editorRoundTrip(stored: any) {
    const displayed = jsonModalSeed(stored);
    const parsed = JSON.parse(displayed);
    const validated = discordMessageImportShape.parse(parsed) as any;
    const disposition = resolveContentLoss(
      validated.flags, validated.components, validated.content, validated.embeds,
    );
    if (disposition.requiresChoice) throw Error('fixture is row E — commitLoad would not load it');
    const next = applyDisposition(validated);
    return { displayed, disposition, saved: loadAndSaveViaShippedProvider(stored, next) };
  }

  const STORED_5712_FULL = {
    id: '5712',
    name: 'MOTM',
    data: {
      username: 'MOTM',
      flags: 32768,
      content: 'Complimenti {{user}} ! Sei il Member of The Month in ...',
      embeds: [],
      components: [],
    },
  };

  it('THE FALSITY SIGNATURE ITSELF — 5712 does NOT still carry flags 32768 after Load and save', () => {
    const { saved } = editorRoundTrip(STORED_5712_FULL);
    expect((saved.data.flags ?? 0) & IS_COMPONENTS_V2_FLAG).toBe(0);
  });

  it('and the repair is genuinely LOSSLESS for 5712 — the content survives', () => {
    const { saved } = editorRoundTrip(STORED_5712_FULL);
    expect(saved.data.content).toBe(STORED_5712_FULL.data.content);
    expect(validateMessage({ ...saved.data, username: 'MOTM' } as unknown as MessageData)).toBe('');
  });

  it('the flag DOES now reach the textarea (the silent strip is retired)', () => {
    const { displayed } = editorRoundTrip(STORED_5712_FULL);
    expect(JSON.parse(displayed).flags).toBe(IS_COMPONENTS_V2_FLAG);
  });

  it('...and the repair is what clears it: row D resolves to classic, and Load applies that', () => {
    const { disposition, saved } = editorRoundTrip(STORED_5712_FULL);
    expect(disposition.mode).toBe('classic');
    expect(disposition.requiresChoice).toBe(false);
    expect((saved.data.flags ?? 0) & IS_COMPONENTS_V2_FLAG).toBe(0);
  });

  /* --- B3 class: a record carrying a stranded V2 flag alongside classic content and a non-V2 Action Row --- */
  const STORED_B3 = {
    id: 'b3',
    name: 'legacy-with-stranded-flag',
    data: {
      username: 'U',
      flags: 32768,
      content: 'Hi',
      embeds: [],
      components: [{ type: 1, components: [{ type: 2, style: 5, label: 'x', url: 'https://e.com' }] }],
    },
  };

  it('B3 class: the editor path is now LOSSLESS — flag cleared, content AND Action Row survive', () => {
    const { disposition, saved } = editorRoundTrip(STORED_B3);
    expect(disposition.mode).toBe('classic');
    expect((saved.data.flags ?? 0) & IS_COMPONENTS_V2_FLAG).toBe(0);
    expect(saved.data.content).toBe('Hi');
    expect(saved.data.components).toHaveLength(1);
    expect((saved.data.components as any)[0].type).toBe(1);
  });

  it('B3 class: the toggle path preserves the Action Row but DESTROYS the content', () => {
    const draft: Draft = { ...STORED_B3.data } as Draft;
    const step2 = switchToClassic(
      switchToV2(draft as unknown as MessageData),
    ) as unknown as Draft;
    expect((step2.flags ?? 0) & IS_COMPONENTS_V2_FLAG).toBe(0);
    expect(step2.components).toEqual([draft.components![0]]);
    expect(step2.content).toBe('');
  });

  it('the editor path is now lossless; the toggle path still is not', () => {
    const viaEditor = editorRoundTrip(STORED_B3).saved.data;
    const viaToggle = switchToClassic(
      switchToV2({ ...STORED_B3.data } as unknown as MessageData),
    ) as unknown as Draft;

    const editorLostComponents = (viaEditor.components ?? []).length === 0;
    const editorLostContent = !viaEditor.content;
    expect([editorLostComponents, editorLostContent]).toEqual([false, false]);

    expect(viaToggle.content).toBe('');
    expect(viaToggle.components).toEqual([STORED_B3.data.components[0]]);
  });
});
